{
  "outcome": "escalate",
  "rationale": "We are escalating this claim because automated findings raised a duplicate claim fraud flag matching an earlier claim. Under Section 7, claims that have already been reported must be escalated to the special investigation unit.",
  "citations": [
    {
      "clause_id": "STD-7.2",
      "quote": "A claim for a loss that has already been reported to us, or paid, under this policy or any other policy, must be escalated to the special investigation unit."
    }
  ]
}
